  $('#quizArea').innerHTML=l.quiz.map((q,qi)=>`<article class="quiz-card" data-q="${qi}"><div class="quiz-number">${qi+1}</div><div><div class="quiz-type">${escapeHtml(q[4]||'閱讀理解')}</div><h3>${escapeHtml(q[0])}</h3><div class="quiz-options">${q[1].map((o,oi)=>`<button type="button" data-answer="${oi}">${String.fromCharCode(65+oi)}. ${escapeHtml(o)}</button>`).join('')}</div><div class="quiz-feedback" hidden></div></div></article>`).join('');
  let score=0, answered=new Set(); $$('.quiz-card').forEach(card=>{ card.querySelectorAll('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>{ const qi=Number(card.dataset.q); if(answered.has(qi)) return; answered.add(qi); const q=l.quiz[qi], chosen=Number(btn.dataset.answer), good=chosen===q[2]; if(good) score++; $('#quizScore').textContent=score; card.querySelectorAll('[data-answer]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===q[2]);b.classList.toggle('wrong',i===chosen&&!good);}); const fb=card.querySelector('.quiz-feedback'); fb.hidden=false; fb.className=`quiz-feedback ${good?'good':'needs-work'}`; fb.innerHTML=`<strong>${good?'答對了！':'再找一次證據。'}</strong><span>題型：${escapeHtml(q[4]||'閱讀理解')} · 線索在短文第 ${q[3]+1} 句。</span>`; const sentence=$(`.read-sentence[data-sentence="${q[3]}"]`); sentence?.classList.add('evidence'); setTimeout(()=>sentence?.classList.remove('evidence'),3500); if(answered.size===l.quiz.length){markLessonStep('quiz'); if(score===l.quiz.length){state.xp+=5;state.weeklyXp+=5;saveState();updateUI();showToast(`閱讀偵探 ${score}/${l.quiz.length}！+5 XP 🔎`);}} })); });
