function resizeCanvas(){ if(!canvas)return; const rect=canvas.getBoundingClientRect(); dpr=Math.min(window.devicePixelRatio||1,2); const old=strokes.map(s=>s.map(p=>({...p}))); canvas.width=Math.max(1,Math.floor(rect.width*dpr)); canvas.height=Math.max(1,Math.floor(rect.height*dpr)); ctx=canvas.getContext('2d'); ctx.setTransform(dpr,0,0,dpr,0,0); strokes=old; redraw(); }
function getPoint(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top,p:e.pressure||.5};}
function drawStroke(points){ if(!points||points.length<2)return; ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#242743';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];ctx.quadraticCurveTo(a.x,a.y,(a.x+b.x)/2,(a.y+b.y)/2);}ctx.stroke();ctx.restore(); }
function redraw(){if(!ctx)return;const r=canvas.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);strokes.forEach(drawStroke);if(currentStroke)drawStroke(currentStroke);}
function clearWriting(){strokes=[];currentStroke=null;redraw();}
function startStroke(e){ if(e.pointerType==='touch'||e.pointerType==='pen'||e.pointerType==='mouse'){e.preventDefault();e.stopPropagation();} isDrawing=true; canvas.setPointerCapture?.(e.pointerId); currentStroke=[getPoint(e)]; redraw(); }
function moveStroke(e){ if(!isDrawing||!currentStroke)return; e.preventDefault();e.stopPropagation();currentStroke.push(getPoint(e));redraw(); }
function endStroke(e){ if(!currentStroke)return; e.preventDefault();e.stopPropagation();if(currentStroke.length>1)strokes.push(currentStroke);currentStroke=null;isDrawing=false;redraw(); }
function blockTouchScroll(e){ if(e.cancelable)e.preventDefault(); e.stopPropagation(); }
function loadMission(index){missionIndex=Math.max(0,Math.min(index,missionQueue.length-1));hintStage=0;clearWriting();const m=missionQueue[missionIndex];$('#missionIndex').textContent=missionIndex+1;$('#missionTotal').textContent=missionQueue.length;$('#missionTitle').textContent=`把「${m.char}」寫回來`;$('#promptSentence').textContent=m.sentence;$('#hintStage').textContent='0 / 3';$('#hintText').textContent='先不要看答案，想想這個字的部首或結構。';$('#ghostCharacter').textContent='';$('#answerCharacter').textContent=m.char;$('#imeInput').value='';}
$('#hintButton')?.addEventListener('click',()=>{const m=missionQueue[missionIndex];hintStage=Math.min(3,hintStage+1);$('#hintStage').textContent=`${hintStage} / 3`;$('#hintText').textContent=m.hints[hintStage-1]||m.hints[2];$('#ghostCharacter').textContent=hintStage===3?m.char:'';if(hintStage===3)setTimeout(()=>{$('#ghostCharacter').textContent='';showToast('字形提示已收起，現在自己寫一次！');},2300);});
$('#undoButton')?.addEventListener('click',()=>{strokes.pop();redraw();}); $('#clearButton')?.addEventListener('click',clearWriting);
function copyCanvasToPreview(){const p=$('#previewCanvas'),size=180,pdpr=Math.min(window.devicePixelRatio||1,2);p.width=size*pdpr;p.height=size*pdpr;const c=p.getContext('2d');c.setTransform(pdpr,0,0,pdpr,0,0);c.fillStyle='#fff';c.fillRect(0,0,size,size);const source=canvas.getBoundingClientRect(),scale=size/source.width;c.save();c.scale(scale,scale);strokes.forEach(points=>{c.lineCap='round';c.lineJoin='round';c.strokeStyle='#242743';c.lineWidth=8;c.beginPath();c.moveTo(points[0].x,points[0].y);for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];c.quadraticCurveTo(a.x,a.y,(a.x+b.x)/2,(a.y+b.y)/2);}c.stroke();});c.restore();}
$('#checkButton')?.addEventListener('click',()=>{if(strokes.length<2){showToast('再寫完整一點，我們再來核對。');return;}copyCanvasToPreview();$('#answerCharacter').textContent=missionQueue[missionIndex].char;$('#checkDialog').showModal();});
$('#retryButton')?.addEventListener('click',()=>{$('#checkDialog').close();clearWriting();showToast('很好，再回想一次會記得更牢。');});
$('#correctButton')?.addEventListener('click',()=>{const ch=missionQueue[missionIndex].char;if(!state.completedChars.includes(ch)){state.completedChars.push(ch);state.xp+=4;state.weeklyXp+=4;state.rescued+=1;state.goalDone=Math.min(5,state.goalDone+1);}saveState();updateUI();$('#checkDialog').close();if(missionIndex<missionQueue.length-1){loadMission(missionIndex+1);showToast(`「${ch}」救回來了 +4 XP`);setTimeout(resizeCanvas,50);}else{$('#handwritingDialog').close();closeHandwritingDialog();markLessonStep('hand');showToast('這組手寫任務完成！🎉');}});
$('#readSentence')?.addEventListener('click',()=>{speechSynthesis.cancel();speakText($('#promptSentence').textContent.replaceAll('＿＿','空格'),.82);});
$('#imeInput')?.addEventListener('input',e=>{if(e.target.value===missionQueue[missionIndex].char)showToast('系統輸入辨識到了！接著也試試田字格默寫。');});
window.addEventListener('resize',()=>{if($('#handwritingDialog').open)resizeCanvas();});
canvas=$('#writingCanvas');canvas.addEventListener('pointerdown',startStroke,{passive:false});canvas.addEventListener('pointermove',moveStroke,{passive:false});canvas.addEventListener('pointerup',endStroke,{passive:false});canvas.addEventListener('pointercancel',endStroke,{passive:false});canvas.addEventListener('touchstart',blockTouchScroll,{passive:false});canvas.addEventListener('touchmove',blockTouchScroll,{passive:false});$('#canvasWrap')?.addEventListener('touchmove',blockTouchScroll,{passive:false});

function findCharInfo(ch){ for(const l of lessons){ const row=l.chars.find(x=>x[0]===ch); if(row) return {lesson:l.id,zhuyin:row[1],word:row[2]}; } return {lesson:'—',zhuyin:'',word:''}; }
function renderRescue(){ $('#rescueWords').innerHTML=rescueMissions.map((m,i)=>{const info=findCharInfo(m.char);return `<button class="word-chip" type="button" data-rescue-index="${i}"><span>${m.char}</span><b>${escapeHtml(info.zhuyin)}</b><small>第 ${info.lesson} 課 · ${i===0?'昨天忘了 2 次':i===1?'3 天後複習':'今日練習'}</small></button>`;}).join(''); $$('[data-rescue-index]').forEach(b=>{b.addEventListener('click',()=>{missionQueue=[rescueMissions[Number(b.dataset.rescueIndex)]];loadMission(0);openHandwritingDialog();});}); }


// ---------------- V4.0 月考模擬 A/B 卷 ----------------
let currentExam=null, examTimerId=null, examSeconds=45*60;
const examBlueprints={
  'midterm-A':{range:'midterm',variant:'A',reading:[1,4]},
  'midterm-B':{range:'midterm',variant:'B',reading:[3,6]},
  'final-A':{range:'final',variant:'A',reading:[7,11]},
  'final-B':{range:'final',variant:'B',reading:[8,12]}
};
function seededRandom(seed){ let h=2166136261; for(const ch of seed){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);} return ()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;}; }
function shuffleSeed(arr,seed){const a=[...arr],r=seededRandom(seed);for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function pickAcross(ls,field,count,seed){const pools=ls.map((l,i)=>shuffleSeed(l[field].map(x=>({item:x,lesson:l})),seed+'-'+i));const out=[];let round=0;while(out.length<count&&round<20){for(let i=0;i<pools.length&&out.length<count;i++){if(pools[i][round])out.push(pools[i][round]);}round++;}return out;}
function uniqueOptions(correct,pool,count,seed,key=x=>x){const vals=[correct];for(const x of shuffleSeed(pool,seed)){if(vals.some(v=>key(v)===key(x)))continue;vals.push(x);if(vals.length>=count)break;}return shuffleSeed(vals,seed+'-mix');}
function maskChar(word,ch){return word.split(ch).join('＿＿');}
function buildExam(key){
  const bp=examBlueprints[key], ls=lessons.filter(l=>l.range===bp.range), seed='exam-'+key;
  const charPool=ls.flatMap(l=>l.chars.map(x=>({x,l}))), vocabPool=ls.flatMap(l=>l.vocab.map(x=>({x,l})));
  const chosenChars=pickAcross(ls,'chars',15,seed+'-chars');
  const sound=chosenChars.slice(0,10).map((o,i)=>{
    const [ch,z,w]=o.item;
    if(i<5){const opts=uniqueOptions(z,charPool.map(a=>a.x[1]).filter(v=>v!==z),4,seed+'-z'+i,x=>x);return {id:'s'+i,cat:'字音字形',points:2,prompt:`「${ch}」在「${w}」中的注音是哪一個？`,options:opts,answer:opts.indexOf(z),correct:z,lesson:o.lesson.id};}
    const candidates=charPool.filter(a=>a.x[0]!==ch&&a.x[1]!==z).map(a=>a.x[0]); const opts=uniqueOptions(ch,candidates,4,seed+'-c'+i,x=>x);return {id:'s'+i,cat:'字音字形',points:2,prompt:`「${maskChar(w,ch)}」空格中讀作 ${z} 的國字是哪一個？`,options:opts,answer:opts.indexOf(ch),correct:ch,lesson:o.lesson.id};
  });
  const meanings=pickAcross(ls,'vocab',10,seed+'-vocab').map((o,i)=>{const [w,m]=o.item;const allMean=vocabPool.map(a=>a.x[1]).filter(x=>x!==m);const opts=uniqueOptions(m,allMean,4,seed+'-m'+i,x=>x);return {id:'m'+i,cat:'詞語理解',points:2,prompt:`「${w}」最接近下面哪一個意思？`,options:opts,answer:opts.indexOf(m),correct:m,lesson:o.lesson.id};});
  const dictation=chosenChars.slice(10,15).map((o,i)=>{const [ch,z,w]=o.item;return {id:'d'+i,cat:'字音字形',points:4,prompt:`${maskChar(w,ch)}（${z}）`,answerText:ch,correct:ch,lesson:o.lesson.id};});
  const readLessons=bp.reading.map(id=>lessons.find(l=>l.id===id)); const reading=[];readLessons.forEach((l,li)=>{const qs=shuffleSeed(l.quiz,seed+'-r'+li).slice(0,li===0?3:2);qs.forEach((q,j)=>reading.push({id:`r${li}-${j}`,cat:'閱讀理解',points:4,prompt:q[0],options:q[1],answer:q[2],correct:q[1][q[2]],type:q[4]||'閱讀理解',lesson:l.id,passage:l.passage,title:l.title}));});
  const makes=pickAcross(ls,'make',2,seed+'-make').map((o,i)=>({id:'e'+i,cat:'表達運用',points:5,char:o.item[0],refs:o.item[1],lesson:o.lesson.id,prompt:`請用「${o.item[0]}」造 2 個詞。`}));
  const sent=pickAcross(ls,'sentence',1,seed+'-sent')[0]; const sentence={id:'e2',cat:'表達運用',points:10,word:sent.item[0],hint:sent.item[1],lesson:sent.lesson.id,prompt:`請用「${sent.item[0]}」造一個完整句子。`};
  return {key,...bp,lessons:ls,sound,meanings,dictation,reading,makes,sentence};
}
function examRangeName(range){return range==='midterm'?'期中｜第 1～6 課':'期末｜第 7～12 課';}
function renderExamPaperGrid(){
  const cards=Object.keys(examBlueprints).map(key=>{const b=examBlueprints[key],r=state.examResults[key];return `<article class="exam-paper-card ${b.range} clickable-card" data-open-exam="${key}" role="button" tabindex="0"><div class="paper-letter">${b.variant}</div><div><p class="eyebrow">${b.range==='midterm'?'MIDTERM':'FINAL'}</p><h3>${examRangeName(b.range)} · ${b.variant} 卷</h3><p>字音字形 40 · 詞語 20 · 閱讀 20 · 表達 20</p>${r?`<div class="last-score">上次：<strong>${r.total}</strong> / 100</div>`:'<small>尚未作答</small>'}</div><span class="primary-button paper-cta">${r?'再挑戰':'開始作答'} →</span></article>`;}).join('');
  $('#examPaperGrid').innerHTML=cards; $$('#examPaperGrid [data-open-exam]').forEach(b=>{b.onclick=()=>openExam(b.dataset.openExam);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openExam(b.dataset.openExam);}};}); renderMistakeBank();
}
function renderMistakeBank(){const box=$('#mistakeBank');const arr=state.examMistakes||[];if(!arr.length){box.innerHTML='<div class="empty-mistakes">🎉 目前沒有待複習錯題。做完模擬卷後，答錯的題目會自動出現在這裡。</div>';return;}box.innerHTML=arr.slice(-20).reverse().map((m,i)=>`<details class="mistake-item"><summary><span>${escapeHtml(m.cat)}</span><strong>${escapeHtml(m.prompt)}</strong></summary><div><p>正確答案：<b>${escapeHtml(m.correct)}</b></p><small>${escapeHtml(m.paper)} · 第 ${m.lesson} 課</small></div></details>`).join('');}
function openExam(key,syncHash=true){if(!examBlueprints[key]){showToast('找不到這份題本，請回模擬考場重選。');return;}currentExam=buildExam(key);examSeconds=45*60;clearInterval(examTimerId);examTimerId=null;$('#timerToggle').textContent='開始計時';updateTimer();renderExam(currentExam);navigate('exam');if(syncHash) location.hash=`exam-${key}`;}
function renderExam(ex){
  $('#submitExam').disabled=false;
  $('#examRangeLabel').textContent=examRangeName(ex.range);$('#examTitle').textContent=`月考模擬 ${ex.variant} 卷`;$('#examMeta').textContent=`${ex.range==='midterm'?'第 1～6 課':'第 7～12 課'} · 滿分 100 · 建議 45 分鐘`;$('#examResult').hidden=true;$('#examResult').innerHTML='';
  const mc=(qs,start)=>qs.map((q,i)=>`<article class="exam-question" data-exam-id="${q.id}"><div class="q-head"><span>${start+i}</span><b>${q.points} 分</b></div><p>${escapeHtml(q.prompt)}</p><div class="exam-options">${q.options.map((o,oi)=>`<label><input type="radio" name="${q.id}" value="${oi}"><span>${String.fromCharCode(65+oi)}. ${escapeHtml(o)}</span></label>`).join('')}</div></article>`).join('');
  const dict=ex.dictation.map((q,i)=>`<article class="exam-question dictation" data-exam-id="${q.id}"><div class="q-head"><span>${21+i}</span><b>4 分</b></div><p>請寫出空格中的國字：<strong>${escapeHtml(q.prompt)}</strong></p><input class="exam-char-input" type="text" maxlength="1" inputmode="text" autocomplete="off" data-text-answer="${q.id}" placeholder="寫 1 個字"></article>`).join('');
  const groups={};ex.reading.forEach(q=>{groups[q.lesson]??=[];groups[q.lesson].push(q);});let n=26;const readHtml=Object.entries(groups).map(([lid,qs])=>{const l=lessons.find(x=>x.id===Number(lid));const qhtml=qs.map(q=>{const num=n++;return `<article class="exam-question reading-q" data-exam-id="${q.id}"><div class="q-head"><span>${num}</span><b>${q.points} 分</b></div><div class="quiz-type">${escapeHtml(q.type)}</div><p>${escapeHtml(q.prompt)}</p><div class="exam-options">${q.options.map((o,oi)=>`<label><input type="radio" name="${q.id}" value="${oi}"><span>${String.fromCharCode(65+oi)}. ${escapeHtml(o)}</span></label>`).join('')}</div></article>`;}).join('');return `<article class="exam-passage"><small>閱讀材料｜第 ${l.id} 課延伸短文</small><h3>${escapeHtml(l.title)}</h3>${l.passage.map(s=>`<p>${escapeHtml(s)}</p>`).join('')}</article>${qhtml}`;}).join('');
  const exp=ex.makes.map((q,i)=>`<article class="exam-question expression-q" data-exam-id="${q.id}"><div class="q-head"><span>${31+i}</span><b>5 分</b></div><p>${escapeHtml(q.prompt)}</p><input type="text" data-expression="${q.id}" placeholder="例如：詞語一、詞語二"></article>`).join('')+`<article class="exam-question expression-q" data-exam-id="${ex.sentence.id}"><div class="q-head"><span>33</span><b>10 分</b></div><p>${escapeHtml(ex.sentence.prompt)}</p><small>${escapeHtml(ex.sentence.hint)}</small><textarea rows="3" data-expression="${ex.sentence.id}" placeholder="請寫完整句子……"></textarea></article>`;
  $('#examContent').innerHTML=`<section class="exam-section"><div class="exam-section-title"><span>一</span><div><h2>字音字形</h2><p>10 題，每題 2 分，共 20 分</p></div></div>${mc(ex.sound,1)}</section><section class="exam-section"><div class="exam-section-title"><span>二</span><div><h2>詞語理解</h2><p>10 題，每題 2 分，共 20 分</p></div></div>${mc(ex.meanings,11)}</section><section class="exam-section"><div class="exam-section-title"><span>三</span><div><h2>國字默寫</h2><p>5 題，每題 4 分，共 20 分；可直接用手機／平板手寫輸入法</p></div></div>${dict}</section><section class="exam-section"><div class="exam-section-title"><span>四</span><div><h2>閱讀理解</h2><p>5 題，每題 4 分，共 20 分</p></div></div>${readHtml}</section><section class="exam-section"><div class="exam-section-title"><span>五</span><div><h2>造詞造句</h2><p>共 20 分，交卷後依參考與檢核表自評</p></div></div>${exp}</section>`;
  $('#examObjectiveTotal').textContent='30';updateExamAnswered();$('#examContent').querySelectorAll('input,textarea').forEach(x=>x.addEventListener('input',updateExamAnswered));
}
function updateExamAnswered(){if(!currentExam)return;const ids=[...currentExam.sound,...currentExam.meanings,...currentExam.dictation,...currentExam.reading].map(q=>q.id);let count=0;ids.forEach(id=>{const q=$(`[data-exam-id="${id}"]`);if(q?.querySelector('input[type=radio]:checked')||q?.querySelector('input[type=text]')?.value.trim())count++;});$('#examAnswered').textContent=count;}
function gradeExam(){if(!currentExam)return;const ex=currentExam;let objective=0;const cats={'字音字形':[0,40],'詞語理解':[0,20],'閱讀理解':[0,20]};const mistakes=[];const mcqs=[...ex.sound,...ex.meanings,...ex.reading];mcqs.forEach(q=>{const root=$(`[data-exam-id="${q.id}"]`),checked=root.querySelector('input[type=radio]:checked'),choice=checked?Number(checked.value):-1,good=choice===q.answer;if(good){objective+=q.points;cats[q.cat][0]+=q.points;}else mistakes.push({cat:q.cat,prompt:q.prompt,correct:q.correct,paper:`${examRangeName(ex.range)} ${ex.variant}卷`,lesson:q.lesson});root.classList.toggle('graded-good',good);root.classList.toggle('graded-bad',!good);root.querySelectorAll('input').forEach(i=>i.disabled=true);const note=document.createElement('div');note.className=`exam-answer ${good?'good':'needs-work'}`;note.textContent=good?'✓ 答對了':`正確答案：${q.correct}`;root.appendChild(note);});
  ex.dictation.forEach(q=>{const root=$(`[data-exam-id="${q.id}"]`),input=root.querySelector('input[type=text]'),val=input.value.trim(),good=val===q.answerText;if(good){objective+=q.points;cats['字音字形'][0]+=q.points;}else mistakes.push({cat:q.cat,prompt:q.prompt,correct:q.correct,paper:`${examRangeName(ex.range)} ${ex.variant}卷`,lesson:q.lesson});input.disabled=true;const note=document.createElement('div');note.className=`exam-answer ${good?'good':'needs-work'}`;note.textContent=good?'✓ 寫對了':`正確字：${q.correct}`;root.appendChild(note);});
  const dedup=new Map((state.examMistakes||[]).map(m=>[m.paper+'|'+m.prompt,m]));mistakes.forEach(m=>dedup.set(m.paper+'|'+m.prompt,m));state.examMistakes=[...dedup.values()].slice(-60);
  renderExpressionReview(ex,objective,cats);document.querySelector('#submitExam').disabled=true;clearInterval(examTimerId);examTimerId=null;saveState();renderMistakeBank();$('#examResult').scrollIntoView({behavior:'smooth',block:'start'});
}
function renderExpressionReview(ex,objective,cats){let awarded=false;const result=$('#examResult');result.hidden=false;result.innerHTML=`<div class="result-hero"><div><p class="eyebrow">OBJECTIVE SCORE</p><h2>客觀題 ${objective} / 80</h2><p>再完成下面的造詞造句自評，就得到 100 分總成績。</p></div><div class="score-big">${objective}<small>/80</small></div></div><div class="ability-grid">${Object.entries(cats).map(([k,[s,t]])=>`<div><span>${k}</span><strong>${s}/${t}</strong><div class="ability-bar"><i style="width:${t?Math.round(s/t*100):0}%"></i></div></div>`).join('')}<div><span>表達運用</span><strong id="expressionAbility">待自評/20</strong><div class="ability-bar"><i id="expressionBar" style="width:0%"></i></div></div></div><div class="self-review"><h3>✏️ 表達題自評</h3>${ex.makes.map((q,i)=>{const val=$(`[data-expression="${q.id}"]`).value.trim();return `<article class="self-item"><p><b>${escapeHtml(q.char)}</b>｜你的答案：${escapeHtml(val||'（未作答）')}</p><small>參考：${q.refs.map(escapeHtml).join('、')}</small><div><button data-self="${q.id}" data-score="0">0 分</button><button data-self="${q.id}" data-score="3">3 分</button><button data-self="${q.id}" data-score="5">5 分</button></div></article>`;}).join('')}<article class="self-item"><p><b>${escapeHtml(ex.sentence.word)}</b>｜你的句子：${escapeHtml($(`[data-expression="${ex.sentence.id}"]`).value.trim()||'（未作答）')}</p><small>自評：有用指定詞、意思合理、句子完整且通順。</small><div><button data-self="${ex.sentence.id}" data-score="0">0 分</button><button data-self="${ex.sentence.id}" data-score="6">6 分</button><button data-self="${ex.sentence.id}" data-score="10">10 分</button></div></article><div class="final-score-line">目前總分：<strong id="finalExamScore">${objective}</strong> / 100</div></div>`;const scores={};$$('[data-self]').forEach(b=>b.onclick=()=>{scores[b.dataset.self]=Number(b.dataset.score);b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));const exp=Object.values(scores).reduce((a,b)=>a+b,0);$('#expressionAbility').textContent=`${exp}/20`;$('#expressionBar').style.width=`${exp/20*100}%`;$('#finalExamScore').textContent=objective+exp;if(Object.keys(scores).length===3){const total=objective+exp;state.examResults[ex.key]={total,objective,expression:exp,date:new Date().toISOString()};if(!awarded){awarded=true;if(total>=90){state.xp+=20;state.weeklyXp+=20;showToast('模擬考 90 分以上！+20 XP 🏆');}else if(total>=80){state.xp+=12;state.weeklyXp+=12;showToast('模擬考完成！+12 XP 🌟');}else{state.xp+=8;state.weeklyXp+=8;showToast('完成比滿分更重要，錯題已收好！+8 XP');}}saveState();updateUI();renderExamPaperGrid();}});}
function updateTimer(){const m=String(Math.floor(examSeconds/60)).padStart(2,'0'),s=String(examSeconds%60).padStart(2,'0');$('#examTimer').textContent=`${m}:${s}`;}
$('#timerToggle')?.addEventListener('click',()=>{if(examTimerId){clearInterval(examTimerId);examTimerId=null;$('#timerToggle').textContent='繼續計時';return;}$('#timerToggle').textContent='暫停';examTimerId=setInterval(()=>{examSeconds=Math.max(0,examSeconds-1);updateTimer();if(examSeconds===0){clearInterval(examTimerId);examTimerId=null;showToast('45 分鐘到了，可以先交卷看看。');}},1000);});
$('#submitExam')?.addEventListener('click',gradeExam);$('#printExam')?.addEventListener('click',()=>window.print());$('#clearMistakes')?.addEventListener('click',()=>{state.examMistakes=[];saveState();renderMistakeBank();showToast('錯題回收站已清空。');});
$$('[data-open-exam]').forEach(b=>b.addEventListener('click',()=>openExam(b.dataset.openExam)));

if('serviceWorker' in navigator){
  window.addEventListener('load', async ()=>{
    try{
      const reg=await navigator.serviceWorker.register('./sw.js?v=5.0.0', {updateViaCache:'none'});
      await reg.update();
    }catch(err){ console.warn('Service Worker update skipped:',err); }
  });
}
renderLessonCards();renderRescue();bindLessonOpeners();renderExamPaperGrid();updateUI();
routeFromHash();
